INSERT INTO metrics (country_id, metric_name, value, unit, period, evidence_type, source_id, notes) VALUES ((SELECT id FROM countries WHERE name='China'), 'electricity_net_imports', -17.0, 'TWh', '2024', 'fact', last_insert_rowid(), 'Gross imports and exports are cross-border flows. Negative net imports mean net exports. Domestic production includes output that may be exported. Total energy: IEA 2023 energy balances, TJ divided by 1000000 to get EJ; exports converted from signed balance entries to positive volumes. Electricity: EIA 2024, billion kWh equals TWh. EIA generation totals may differ from the OWID/Ember generation used for the existing source-share columns. IEA balances use different primary-energy accounting from the existing OWID substitution-method shares; do not multiply those shares by these production totals. Electricity imports and exports are preliminary in the EIA source.');
