INSERT INTO metrics (country_id, metric_name, value, unit, period, evidence_type, source_id, notes) VALUES ((SELECT id FROM countries WHERE name='France'), 'electricity_generation_wind_share', 8.09, '%', '2024', 'fact', last_insert_rowid(), 'Shares expressed as percentages (0-100), rounded to 2 decimals. Other is 100 minus the six displayed shares and includes nuclear and other renewables. Electricity oil_and_other_fossil uses OWID oil_share_elec, mapped from Ember Other fossil; not a pure-oil estimate. The primary-energy oil share is separate oil consumption. Mix source: Our World in Data, Ember electricity data (2026), Energy Institute Statistical Review (2025).');
