INSERT INTO metrics (country_id, metric_name, value, unit, period, evidence_type, source_id, notes) VALUES ((SELECT id FROM countries WHERE name='France'), 'electricity_generation_hydro_share', 12.66, '%', '2024', 'fact', last_insert_rowid(), 'Shares expressed as percentages (0-100), rounded to 2 decimals. Other is 100 minus the six displayed shares and includes nuclear and other renewables. Electricity oil_and_other_fossil uses OWID oil_share_elec, mapped from Ember Other fossil; not a pure-oil estimate. The primary-energy oil share is separate oil consumption. Mix source: Our World in Data, Ember electricity data (2026), Energy Institute Statistical Review (2025).');
INSERT INTO sources (name, source_url, publisher, retrieved_at, notes) VALUES ('Electricity production and trade - France', 'https://www.eia.gov/opendata/browser/international?frequency=annual&data=value&facets=productId;countryRegionId;unit&productId=2;&countryRegionId=FRA;&unit=BKWH;&start=2024&end=2024', 'U.S. EIA', '2026-09-16', 'Source recorded in energy-data.csv');
INSERT INTO metrics (country_id, metric_name, value, unit, period, evidence_type, source_id, notes) VALUES ((SELECT id FROM countries WHERE name='France'), 'electricity_net_imports', -89.850955, 'TWh', '2024', 'fact', last_insert_rowid(), 'Gross imports and exports are cross-border flows. Negative net imports mean net exports. Domestic production includes output that may be exported. Total energy: IEA 2023 energy balances, TJ divided by 1000000 to get EJ; exports converted from signed balance entries to positive volumes. Electricity: EIA 2024, billion kWh equals TWh. EIA generation totals may differ from the OWID/Ember generation used for the existing source-share columns. IEA balances use different primary-energy accounting from the existing OWID substitution-method shares; do not multiply those shares by these production totals.');
